SourceCode.Declaration:
/// <summary>
/// Data contract for the EDI Invoice GRN search operation.
/// Stores query criteria and cut-off days used to filter records.
/// </summary>
[DataContract]
class METEDIInvoiceGRNSearchContract implements SysOperationValidatable
{
    private str packedQuery;
    private int cutoffDays;

}

Method.Source:
/// <summary>
/// Gets or sets the packed query value.
/// </summary>
/// <param name="_packedQuery">
/// Base64-encoded packed query.
/// </param>
/// <returns>
/// The packed query value.
/// </returns>
[
    DataMemberAttribute(identifierStr(Query)),
    AifQueryTypeAttribute('_packedQuery', queryStr(METEDIInvoiceGRNQuery))
]
public str parmQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Returns the unpacked query or the default query if no packed query exists.
/// </summary>
/// <returns>
/// Query object containing the search criteria.
/// </returns>
public Query getQuery()
{
    return packedQuery
        ? new Query(SysOperationHelper::base64Decode(packedQuery))
        : new Query(queryStr(METEDIInvoiceGRNQuery));
}

/// <summary>
/// Gets or sets the cut-off days value used by the search operation.
/// </summary>
/// <param name="_cutoffDays">
/// Number of cut-off days. Must be greater than zero.
/// </param>
/// <returns>
/// The cut-off days value.
/// </returns>
[
    DataMemberAttribute(identifierStr(CutoffDays)),
    SysOperationLabel(literalStr("@MET:EDICustOffDays"))
]
public int parmCutoffDays(int _cutoffDays = cutoffDays)
{
    cutoffDays = _cutoffDays;
    return cutoffDays;
}

/// <summary>
/// Validates the contract values before execution of the operation.
/// </summary>
/// <returns>
/// True if validation succeeds; otherwise, false.
/// </returns>
public boolean validate()
{
    boolean isValid = true;

    if (cutoffDays <= 0)
    {
        isValid = checkFailed("@MET:EDIValidateGRNCutOFfDate");
    }

    return isValid;
}
